```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Pendulum Simulation</title>
  <script src="pendulum.js"></script>
</head>
<body>
  <canvas id="pendulum-canvas" width="400" height="400"></canvas>
  <input id="initial-angle" type="number" value="45">
  <button id="release-button">Release Pendulum</button>

  <script>
    let canvas = document.getElementById('pendulum-canvas');
    let ctx = canvas.getContext('2d');
    let initialAngle = 45;
    let angle = initialAngle;
    let velocity = 0;
    let accelerometer = 0;
    let gravity = 9.81;
    let pendulumLength = canvas.width / 2;

    function update() {
      let axleX = canvas.width / 2;
      let axleY = canvas.height;
      let radius = pendulumLength * Math.cos(Math.radians(angle));

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.lineWidth = 2;
      ctx.strokeStyle = 'black';
      ctx.moveTo(axleX, axleY);
      ctx.lineTo(axleX + radius, axleY - pendulumLength);
      ctx.stroke();

      velocity += accelerometer;
      angle += velocity;

      if (angle > 180) {
        angle = 180;
        velocity = 0;
      } else if (angle < 0) {
        angle = 0;
        velocity = 0;
      }

      requestAnimationFrame(update);
    }

    function releasePendulum() {
      initialAngle = document.getElementById('initial-angle').value;
      angle = Math.radians(initialAngle);
      velocity = 0;
      accelerometer = -gravity / pendulumLength;
      update();
    }

    document.getElementById('release-button').addEventListener('click', releasePendulum);

    function radians(degrees) {
      return degrees * Math.PI / 180;
    }

    update();
  </script>
</body>
</html>
```

