Here is an example C++ program that uses the pigpio library to control GPIO pin 12 on a Raspberry Pi 4B:
```
#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  if (pigpioInitialise() != 0) {
    std::cerr << "pigpio initialisation failed" << std::endl;
    return 1;
  }

  // Set pin 12 as an output
  gpioSetup(12, PI_OUTPUT);

  // Set the initial state of the pin to off (low)
  gpioWrite(12, 0);

  // Main loop
  while (true) {
    // Toggle the pin on and off
    gpioWrite(12, gpioRead(12) ? 0 : 1);

    // Sleep for 1 second
    delay(1000);
  }

  // Clean up
  pigpioTerminate();
  return 0;
}
```
